return UnityEngine.Object.FindObjectsByType<MeshRenderer>(FindObjectsSortMode.None).Where(r=>r.sharedMaterials.Any(m=>m&&m.name.Contains("Asphalt_DoubleLine"))).Take(8).Select(r=>{var mf=r.GetComponent<MeshFilter>();var uv=mf&&mf.sharedMesh?mf.sharedMesh.uv:new Vector2[0];return new{name=r.name,root=r.transform.root.name,size=r.bounds.size.ToString(),materials=r.sharedMaterials.Where(m=>m).Select(m=>new{name=m.name,scale=m.GetTextureScale("_BaseMap").ToString(),offset=m.GetTextureOffset("_BaseMap").ToString()}).ToArray(),uvMin=uv.Length>0?new Vector2(uv.Min(v=>v.x),uv.Min(v=>v.y)).ToString():null,uvMax=uv.Length>0?new Vector2(uv.Max(v=>v.x),uv.Max(v=>v.y)).ToString():null};}).ToArray();
